-- Home scene definitions extracted from MasterData_RegionTw_Production.bytes.
-- Unity bundle hash: a3420859ca359a49fd29dda1db0b97b1
-- TextAsset SHA256: 730d2aea3e7138d0212b64d80d7fe13e2c72ff03086944f3c8d2e325b4b592cc
-- Columns in each scene: [situation code, minimum closeness level, event codes].
-- Costume/situation/event links and unlock thresholds come from master tables, not code arithmetic.
-- Only ordinary appearance/talk scenes are included; conditional scene events are not unlocked.
CREATE TABLE IF NOT EXISTS public.home_costume_scenes (
    costume_code BIGINT PRIMARY KEY,
    home_character_code BIGINT NOT NULL,
    scenes JSONB NOT NULL CHECK (jsonb_typeof(scenes) = 'array'),
    source_sha256 TEXT NOT NULL
);
ON CONFLICT (costume_code) DO NOTHING;
